void transport_audio_path_tests(const std::filesystem::path& dir){
    AudioPathDocument path;const auto config=path.save_bytes();SegmentDocument segment;
    const auto source=segment.save_bytes();
    write_file_atomic((dir/L"source.sgp").wstring(),source);write_file_atomic((dir/L"default.aup").wstring(),config);
    require(prepare_transport_audio_path(source,{})==source,"standard default retains Segment exact bytes");
    const auto selected=prepare_transport_audio_path(source,config);const auto root=Chunk::parse(selected);const auto ap=root.find("RIFF","DMAP");
    require(ap&&ap->encode()==config,"default AudioPath copied whole bytes");
    auto rest=root;rest.children.pop_back();require(rest.encode()==source,"private Segment retains every other byte");
    require(segment.save_bytes()==source&&!segment.dirty(),"default playback does not dirty source");
    write_file_atomic((dir/L"selected.sgp").wstring(),selected);
    AudioPathDocument other;other.set_name(L"Different transport default");const auto different=other.save_bytes();
    require(different!=config,"different default fixture");write_file_atomic((dir/L"different.aup").wstring(),different);
    require(prepare_transport_audio_path(selected,different)==selected,"embedded setting takes precedence byte exact");
    require(prepare_transport_audio_path(selected,{})==selected,"embedded retained under standard default");
    const auto carrier=prepare_transport_audio_path({},config);const auto carrierRoot=Chunk::parse(carrier);const auto carrierPath=carrierRoot.find("RIFF","DMAP");
    require(carrierPath&&carrierPath->encode()==config,"standalone Motif configuration carrier exact");
    write_file_atomic((dir/L"carrier.sgp").wstring(),carrier);
    require(prepare_transport_audio_path({},{}).empty(),"standard Motif requires no carrier");
    rejected([&]{prepare_transport_audio_path(source,source);},"invalid AudioPath refused without altering inputs");
    rejected([&]{prepare_transport_audio_path(config,different);},"non Segment playback context refused");
}

void dls_wave_creation_tests(const std::filesystem::path& dir,const std::wstring& wavPath,const std::wstring& observedPath){
    const auto base=dir/L"WaveFactory";std::filesystem::create_directories(base);const auto input=read_file(wavPath);const auto portable=Chunk::parse(input);
    Framework host;host.new_collection();auto& d=host.collection_document(0);const auto empty=d.save_bytes();
    require(d.add_wave_pcm(input,"Tone")&&d.waves().size()==1&&d.instruments().empty(),"new PCM Wave in empty Collection");const auto first=d.save_bytes();
    const auto exported=Chunk::parse(d.export_wave_pcm(0));require(d.waves()[0].channels==1&&d.waves()[0].sampleRate==8000&&d.waves()[0].bits==16&&d.waves()[0].frames==800&&exported.find("data")->data==portable.find("data")->data&&std::equal(portable.find("fmt ")->data.begin(),portable.find("fmt ")->data.begin()+16,exported.find("fmt ")->data.begin()),"Wave creation retains complete input PCM");d.validate_playback_samples();
    const auto root=Chunk::parse(first);const auto& wave=root.find("LIST","wvpl")->children.at(0);const auto id=wave.find("guid")->data;
    require(collection_identity(first)==collection_identity(empty),"Wave creation retains Collection identity");
    require(id.size()==16&&std::any_of(id.begin(),id.end(),[](auto b){return b!=0;})&&wave.find("wsmp")->data[4]==60&&d.wave_loops(0).empty(),"Wave identity and default sample settings");
    require(d.undo()&&d.save_bytes()==empty&&!d.undo()&&d.redo()&&d.save_bytes()==first,"Wave append is exactly one whole-byte transaction");
    d.undo();auto bad=portable;bad.find("data")->data.pop_back();rejected([&]{d.add_wave_pcm(bad.encode(),"Tone");},"partial PCM frame rejected");
    bad=portable;bad.children.push_back(*bad.find("data"));rejected([&]{d.add_wave_pcm(bad.encode(),"Tone");},"ambiguous Wave samples rejected");
    bad=portable;bad.find("fmt ")->data[0]=3;rejected([&]{d.add_wave_pcm(bad.encode(),"Tone");},"unsupported float PCM rejected");
    bad=portable;Chunk sampler;sampler.id="smpl";sampler.data=Bytes(36,0);bad.children.push_back(sampler);rejected([&]{d.add_wave_pcm(bad.encode(),"Tone");},"unimplemented sampler import rejects instead of losing metadata");
    rejected([&]{d.add_wave_pcm(input,std::string("bad\0name",8));},"embedded NUL name rejected");
    require(d.save_bytes()==empty&&!d.undo()&&d.redo()&&d.save_bytes()==first,"failed imports preserve bytes and redo history");
    host.save_collection(0,(base/L"Created.dlp").wstring());host.save_project((base/L"WaveFactory.pro").wstring());const auto project=read_file((base/L"WaveFactory.pro").wstring());
    Framework reload;reload.open_project((base/L"WaveFactory.pro").wstring());require(reload.collection_document(0).save_bytes()==first&&!reload.dirty(),"new Wave native Project separate Framework reload");reload.save_project((base/L"WaveFactory.pro").wstring());require(read_file((base/L"WaveFactory.pro").wstring())==project,"new Wave native Project exact resave");
    auto existing=Chunk::parse(read_file(observedPath));Chunk opaque;opaque.id="zzzz";opaque.data={1,2,3};opaque.padding=0xad;auto& pool=*existing.find("LIST","wvpl");pool.children.insert(pool.children.begin(),opaque);
    auto& table=existing.find("ptbl")->data;table.insert(table.begin()+8,4,0x91);put32(table,0,12);put32(table,8,0x91919191);put32(table,12,static_cast<std::uint32_t>(opaque.encode().size()));table.insert(table.end(),4,0);put32(table,4,2);put32(table,16,static_cast<std::uint32_t>(opaque.encode().size()));table.insert(table.end(),{0xaa,0xbb});const auto original=existing.encode();DlsDocument loaded;loaded.load(original);
    require(loaded.add_wave_pcm(input,"Second")&&loaded.waves().size()==2,"append Wave to existing alias-cue Collection");const auto appended=loaded.save_bytes();auto expected=existing;const auto actual=Chunk::parse(appended);expected.find("LIST","wvpl")->children.push_back(actual.find("LIST","wvpl")->children.back());auto& et=expected.find("ptbl")->data;et.insert(et.begin()+20,4,0);put32(et,4,3);put32(et,20,static_cast<std::uint32_t>(opaque.encode().size()+pool.children[1].encode().size()));
    require(appended==expected.encode(),"Wave append preserves existing aliases table extensions unknown chunks and padding");
    require(actual.find("LIST","wvpl")->children.back().find("guid")->data!=id,"separate new Waves have distinct identities");
    require(loaded.undo()&&loaded.save_bytes()==original&&loaded.redo()&&loaded.save_bytes()==appended,"existing Collection append history exact");loaded.validate_playback_samples();loaded.save((base/L"Appended.dlp").wstring());write_file_atomic((base/L"Existing.dlp").wstring(),original);write_file_atomic((base/L"Input.wav").wstring(),input);
}
