    require(identity.size()==16&&std::any_of(identity.begin(),identity.end(),[](auto b){return b!=0;})&&ins.find("LIST","INFO")->find("INAM")->data==Bytes({'F','i','r','s','t',0}),"new Instrument identity and explicit name");
