    require(d.create_instrument(0x80000002,7,"Drum",0)&&d.instruments().size()==2&&d.instruments()[1].bank==0x80000002,"drum locale distinct from melodic locale");const auto second=d.save_bytes();
    require(Chunk::parse(second).find("LIST","lins")->children.back().find("dlid")->data!=identity&&d.undo()&&d.save_bytes()==first&&d.redo()&&d.save_bytes()==second,"separate Instrument identity and append history");d.undo();
    host.save_collection(0,(base/L"Created.dlp").wstring());host.save_project((base/L"InstrumentFactory.pro").wstring());const auto project=read_file((base/L"InstrumentFactory.pro").wstring());Framework reload;reload.open_project((base/L"InstrumentFactory.pro").wstring());
    require(reload.collection_document(0).save_bytes()==first&&!reload.dirty(),"new Instrument native Project separate Framework reload");reload.save_project((base/L"InstrumentFactory.pro").wstring());require(read_file((base/L"InstrumentFactory.pro").wstring())==project,"new Instrument native Project exact resave");
    reload.new_band();reload.add_band_gm_instrument(0,0,4,64,100);reload.save_band(0,(base/L"Assigned.bnp").wstring());require(reload.set_band_collection_instrument(0,0,0,0)&&reload.band_document(0).instruments()[0].patch==519&&reload.band_collections(0)[0].bytes==first,"new Instrument Band assignment and playback dependency snapshot");reload.save_band(0,(base/L"Assigned.bnp").wstring());reload.save_project((base/L"InstrumentFactory.pro").wstring());Framework mixed;mixed.open_project((base/L"InstrumentFactory.pro").wstring());require(mixed.band_collections(0)[0].bytes==first&&!mixed.dirty(),"new Instrument and assigned Band native reload");
    auto extended=Chunk::parse(read_file(observedPath));Chunk opaque;opaque.id="zzzz";opaque.data={1,2,3};opaque.padding=0xab;extended.children.push_back(opaque);extended.find("LIST","lins")->children.push_back(opaque);extended.find("colh")->data.insert(extended.find("colh")->data.end(),{0x91,0x92});auto& table=extended.find("ptbl")->data;table.insert(table.end(),4,0);put32(table,4,2);table.insert(table.end(),{0xcc,0xdd});const auto prior=extended.encode();DlsDocument loaded;loaded.load(prior);
    require(loaded.create_instrument(256,0,"Alias",1)&&loaded.instruments()[0].regions[0].tableIndex==1,"Instrument can link alias cue without renumbering");const auto appended=loaded.save_bytes();auto raw=Chunk::parse(appended);auto wanted=extended;wanted.find("LIST","lins")->children.push_back(raw.find("LIST","lins")->children.back());put32(wanted.find("colh")->data,0,1);
    require(appended==wanted.encode()&&loaded.undo()&&loaded.save_bytes()==prior&&loaded.redo()&&loaded.save_bytes()==appended,"Instrument append preserves aliases tails opaque chunks odd padding and whole history");loaded.save((base/L"Extended.dlp").wstring());write_file_atomic((base/L"BeforeExtended.dlp").wstring(),prior);
    auto bad=original;auto& wave=bad.find("LIST","wvpl")->children[0];wave.find("fmt ")->data[2]=2;put32(wave.find("fmt ")->data,8,32000);wave.find("fmt ")->data[12]=4;DlsDocument unsupported;unsupported.load(bad.encode());const auto unchanged=unsupported.save_bytes();rejected([&]{unsupported.create_instrument(0,0,"Stereo",0);},"unimplemented stereo Region placement rejected");require(unsupported.save_bytes()==unchanged&&!unsupported.undo(),"unsupported Region cannot publish an empty Instrument");
