void append_track_position_tests(const std::filesystem::path& dir){
    const auto base=dir/L"track-position";std::filesystem::create_directories(base);
    BandDocument band;band.add_gm_instrument(0,0,64,100);const auto bandBytes=band.save_bytes();
    SegmentDocument d;d.add_tempo(0,120);
    for(const unsigned group:{1u,2u,4u}){d.select_track_group(group);require(d.add_note({96,48,0,60,90})&&d.set_band(96,bandBytes),"New selected Sequence/Band pair created");}
    const auto generated=d.save_bytes();const auto tree=Chunk::parse(generated);const auto& tracks=tree.find("LIST","trkl")->children;
    require(tracks.size()==7,"Generated position fixture has seven tracks");
    for(size_t i=0;i<tracks.size();++i)require(read32(tracks[i].find("trkh")->data,16)==i,"Appended Sequence/Band positions increase across types and groups");
    write_file_atomic((base/L"generated.sgp").wstring(),generated);
    // Imported sparse positions and extended headers remain byte-for-byte;
    // new position follows the maximum rather than the list length.
    auto sparse=tree;auto list=sparse.find("LIST","trkl");put32(list->children[2].find("trkh")->data,16,900);list->children[2].find("trkh")->data.resize(36,0xc8);
    const auto before=sparse.encode();d.load(before);d.select_track_group(8);require(d.add_note({0,48,0,64,90}),"Append after imported sparse position");
    const auto after=Chunk::parse(d.save_bytes());const auto& appended=after.find("LIST","trkl")->children;require(read32(appended.back().find("trkh")->data,16)==901,"New track follows maximum imported position");
    for(size_t i=0;i<list->children.size();++i)require(appended[i].encode()==list->children[i].encode(),"Appending preserves imported track including extended header");
    require(d.undo()&&d.save_bytes()==before&&!d.dirty(),"Undo appended position restores exact checkpoint");require(d.redo()&&d.save_bytes()==after.encode(),"Redo retains assigned position");
    auto exhausted=sparse;put32(exhausted.find("LIST","trkl")->children[2].find("trkh")->data,16,UINT32_MAX);const auto blocked=exhausted.encode();d.load(blocked);d.select_track_group(8);
    rejected([&]{d.add_note({0,48,0,64,90});},"Sequence position overflow rejected");rejected([&]{d.set_band(0,bandBytes);},"Band position overflow rejected");require(d.save_bytes()==blocked&&!d.dirty()&&!d.undo()&&d.notes().empty()&&d.band_events().empty(),"Overflow leaves bytes caches checkpoint and history intact");
}
