Chunk style_fixture(unsigned beats,unsigned denominator,unsigned grids,double tempo,bool sdk=false) {
    Chunk root;root.id="RIFF";root.type="DMST";Chunk header;header.id="styh";header.data.resize(sdk?16:12);header.data[0]=static_cast<BYTE>(beats);header.data[1]=static_cast<BYTE>(denominator);header.data[2]=static_cast<BYTE>(grids);header.data[3]=static_cast<BYTE>(grids>>8);std::memcpy(header.data.data()+(sdk?8:4),&tempo,8);root.children.push_back(header);
    Chunk id;id.id="guid";id.data=Bytes(16,0x42);root.children.push_back(id);Chunk opaque;opaque.id="zzzz";opaque.data={7,8,9};opaque.padding=0xa5;root.children.push_back(opaque);return root;
}
Chunk style_reference(const std::wstring& file,std::uint32_t time=0) {
    Chunk ref;ref.id="LIST";ref.type="strf";Chunk stamp;stamp.id="stmp";stamp.data.resize(4);put32(stamp.data,0,time);ref.children.push_back(stamp);
    Chunk descriptor;descriptor.id="LIST";descriptor.type="DMRF";Chunk header;header.id="refh";header.data={0x8a,0x28,0xac,0xd2,0x9b,0xb3,0xd1,0x11,0x87,4,0,0x60,8,0x93,0xb1,0xbd,0x13,0,0,0};descriptor.children.push_back(header);Chunk guid;guid.id="guid";guid.data=Bytes(16,0x42);descriptor.children.push_back(guid);Chunk filename;filename.id="file";filename.data=utf16(file);descriptor.children.push_back(filename);ref.children.push_back(descriptor);return ref;
}
