    SegmentDocument empty;auto root=Chunk::parse(empty.save_bytes());Chunk track;track.id="RIFF";track.type="DMTK";Chunk header;header.id="trkh";header.data={0x8d,0x28,0xac,0xd2,0x9b,0xb3,0xd1,0x11,0x87,4,0,0x60,8,0x93,0xb1,0xbd};header.data.resize(32);put32(header.data,20,1);std::memcpy(header.data.data()+28,"sttr",4);track.children.push_back(header);Chunk refs;refs.id="LIST";refs.type="sttr";refs.children=references;track.children.push_back(refs);root.find("LIST","trkl")->children.push_back(track);return root.encode();
