void pattern_ownership_tests(const std::filesystem::path& dir,const std::wstring& segmentPath,const std::wstring& stylePath){
    const auto base=dir/L"pattern-ownership";std::filesystem::create_directories(base);
    const auto original=read_file(stylePath),segment=read_file(segmentPath);StyleDocument d;d.load(original);
    require(d.patterns().size()==2&&d.parts().size()==2&&d.part_references(0).size()==1,"owned two-Pattern fixture binding");
    const auto originalTree=Chunk::parse(original);const auto sourcePart=d.part_references(0)[0].partIndex;
    require(!d.duplicate_pattern(2,L"Bad")&&!d.duplicate_pattern(0,L"")&&!d.duplicate_pattern(0,std::wstring(L"Bad\0Name",8))&&d.save_bytes()==original&&!d.undo(),"invalid Pattern copies do not edit history");
    require(!d.unshare_pattern_part(0,0)&&!d.unshare_pattern_part(0,1)&&!d.unshare_pattern_part(2,0)&&d.save_bytes()==original&&!d.undo(),"unique Part and invalid selections do not edit history");
    require(d.duplicate_pattern(0,L"Low Copy"),"duplicate Pattern with shared reference");const auto duplicate=d.save_bytes();
    require(d.patterns().size()==3&&d.patterns()[2].name==L"Low Copy"&&d.parts().size()==2&&d.part_references(2)[0].partIndex==sourcePart,"copy changes name and retains shared Part");
    auto expected=originalTree;auto copy=*expected.find("LIST","pttn");copy.find("LIST","UNFO")->find("UNAM")->data=utf16(L"Low Copy");expected.children.push_back(copy);
    require(duplicate==expected.encode(),"copy preserves all source Pattern chunks and reference flags");
    require(d.undo()&&d.save_bytes()==original&&!d.dirty()&&d.redo()&&d.save_bytes()==duplicate,"Pattern duplication wholebytes UndoRedo");
    require(d.unshare_pattern_part(2,0),"unshare copied Pattern reference");const auto unshared=d.save_bytes();const auto newRef=d.part_references(2)[0];
    require(d.parts().size()==3&&newRef.partIndex==2&&newRef.objectId!=d.parts()[sourcePart].objectId&&d.part_references(0)[0].partIndex==sourcePart,"new Part identity binds selected reference only");
    auto normalized=Chunk::parse(unshared);auto newPart=normalized.children[normalized.children.size()-2];std::copy_n(originalTree.find("LIST","part")->find("prth")->data.begin()+132,16,newPart.find("prth")->data.begin()+132);
    require(newPart.encode()==originalTree.find("LIST","part")->encode(),"new Part preserves all notes variation flags and unknown bytes except GUID");
    normalized.children.erase(normalized.children.end()-2);auto& ref=normalized.children.back().find("LIST","pref")->find("prfc")->data;std::copy_n(copy.find("LIST","pref")->find("prfc")->data.begin(),16,ref.begin());
    require(normalized.encode()==duplicate,"unshare changes only selected GUID and inserts copied Part before binding");
    require(!d.unshare_pattern_part(2,0)&&d.save_bytes()==unshared,"independent Part second unshare is no-op");
    require(d.undo()&&d.save_bytes()==duplicate&&d.redo()&&d.save_bytes()==unshared,"unshare UndoRedo reuses original generated GUID");
    auto note=d.part_notes(newRef.partIndex)[0];StyleNoteEdit value{note.gridStart,note.duration,note.timeOffset,note.variation,72,note.velocity};
    require(d.edit_part_note(newRef.partIndex,0,value)&&d.part_notes(sourcePart)[0].musicValue==60&&d.part_notes(newRef.partIndex)[0].musicValue==72,"independent Part note edit leaves source Pattern unchanged");
    auto malformed=originalTree;malformed.find("LIST","pttn")->find("LIST","pref")->find("prfc")->data[0]^=0x80;StyleDocument bad;bad.load(malformed.encode());
    rejected([&]{bad.duplicate_pattern(0,L"Bad");},"unresolved copy binding rejected");rejected([&]{bad.unshare_pattern_part(0,0);},"unresolved unshare binding rejected");require(bad.save_bytes()==malformed.encode()&&!bad.dirty()&&!bad.undo(),"binding failures preserve bytes and history");
    write_file_atomic((base/L"original.stp").wstring(),original);write_file_atomic((base/L"duplicate.stp").wstring(),duplicate);write_file_atomic((base/L"unshared.stp").wstring(),unshared);
    write_file_atomic((base/L"Heartlnd.stp").wstring(),original);write_file_atomic((base/L"selection.sgp").wstring(),segment);
    Framework host;const auto si=host.open_style((base/L"Heartlnd.stp").wstring()),di=host.open_segment((base/L"selection.sgp").wstring());const auto songBefore=host.document(di).save_bytes();
    require(host.duplicate_style_pattern(si,0,L"Low Copy")&&host.document(di).styles()[0].bytes==host.style_document(si).save_bytes(),"Framework copy publishes owned runtime snapshot");
    require(host.set_pattern_groove(si,0,1,24)&&host.set_pattern_groove(si,2,25,49)&&host.unshare_style_pattern_part(si,2,0),"Framework copy Groove and selected Part separation");
    const auto separated=host.style_document(si).save_bytes();const auto pi=host.style_document(si).part_references(2)[0].partIndex;
    for(size_t n=0;n<4;++n){const auto v=host.style_document(si).part_notes(pi)[n];require(host.edit_style_part_note(si,pi,n,{v.gridStart,v.duration,v.timeOffset,v.variation,72,v.velocity}),"Framework independent note edit");}
    const auto edited=host.style_document(si).save_bytes();require(host.style_document(si).part_notes(0)[0].musicValue==60&&host.document(di).styles()[0].bytes==edited&&host.document(di).save_bytes()==songBefore&&!host.document(di).dirty(),"Framework binding refresh isolates saved Segment and original Part");
    for(int i=0;i<4;++i)require(host.undo_style(si),"Framework note Undo");require(host.style_document(si).save_bytes()==separated&&host.document(di).styles()[0].bytes==separated,"Undo snapshot coherent");
    for(int i=0;i<4;++i)require(host.redo_style(si),"Framework note Redo");require(host.style_document(si).save_bytes()==edited,"Redo restores edited identity and notes");
    host.save_style(si,(base/L"Heartlnd.stp").wstring());host.save_project((base/L"project.dmpj").wstring());Framework reload;reload.open_project((base/L"project.dmpj").wstring());
    require(reload.style_document(0).save_bytes()==edited&&reload.document(0).styles()[0].bytes==edited&&reload.document(0).save_bytes()==segment&&!reload.style_document(0).dirty(),"separate Framework project restores independent Part and runtime snapshot");
    reload.save_style(0,(base/L"resaved.stp").wstring());require(read_file((base/L"resaved.stp").wstring())==edited,"separate Framework re-save exact bytes");
}
