void playback_monitor_tests(){
    PlaybackMonitor monitor;
    require(monitor.update({{1,true,100,50}},0).empty(),"primary playing remembered");
    require(monitor.update({{2,true,200,150},{1,true,200,50}},100).empty(),"both playing remembered independently");
    auto events=monitor.update({{2,false,300,150},{1,true,300,50}},200);
    require(events.size()==1&&events[0].id==2&&events[0].completion==PlaybackCompletion::Ended,"secondary natural end targets its ID only");monitor.forget(2);
    events=monitor.update({{1,false,400,50}},300);
    require(events.size()==1&&events[0].id==1&&events[0].completion==PlaybackCompletion::Ended,"retained ended primary keeps start history");
    monitor.clear();require(monitor.update({{3,false,100,10000}},0).empty(),"future scheduled playback retained");
    require(monitor.update({{3,false,9000,10000}},60000).empty(),"long delay does not start wall timeout");
    require(monitor.update({{3,false,10000,10000}},61000).empty(),"due clock begins grace period");
    require(monitor.update({{3,false,10001,10000}},65999).empty(),"five second grace has not expired");
    events=monitor.update({{3,false,10001,10000},{4,true,10001,9900}},66000);
    require(events.size()==1&&events[0].id==3&&events[0].completion==PlaybackCompletion::StartTimedOut,"only stalled due session times out");
    require(monitor.update({{4,true,10002,9900}},67000).empty(),"removed timeout does not affect playing peer");
    require(monitor.update({},68000).empty(),"removed IDs pruned");
    require(monitor.update({{4,false,100,1000}},69000).empty(),"removed identity has no stale playing history");
    monitor.clear();monitor.observed_start(5);
    events=monitor.update({{5,false,200,100},{6,true,200,100}},1000);
    require(events.size()==1&&events[0].id==5&&events[0].completion==PlaybackCompletion::Ended,"notification proves short instance start missed by samples");
    monitor.forget(5);monitor.observed_start(0);
    require(monitor.update({{6,true,300,100}},2000).empty(),"ignored unknown notification and removed short instance preserve peer");
    monitor.clear();monitor.observed_start(7);require(monitor.update({},3000).empty(),"late retired notification history pruned without completion");
}
